            prerequisites = "تثبيت واعتماد السقالات المعدنية الآمنة، معالجة فواصل صب الخرسانات وإزالة زرجينات وأسلاك النجارة، انتهاء تمديدات صرف المطر والتكييف والكهرباء الخارجية.\nاختبار التغذية والصرف والكهرباء المخفية؛ استلام المباني والحلوق والعلب وتحديد الشرب وسمك التشطيب.",
            requiredMaterials = listOf("أسمنت بورتلاندي مقاوم للكبريتات SRC وأسمنت أبيض", "رمل حرش كوارتزي مغسول", "كسر وحبيبات رخام وحجر طبيعي متدرج", "بودرة حجر جيري وكوارتز ميكروني", "أكاسيد ألوان غير عضوية مقاومة للأشعة فوق البنفسجية", "مواد بوليمرية وإضافات عزل مائي (Sika-1 / Addibond 65)"),
            toolsNeeded = listOf("سقالات معدنية نمطية مطابقة للأمان", "بوشار فولاذي (شاكوش تسنين الحجر الصناعي)", "ماكينة طرطشة ميكانيكية وكمبروسر رش ضهارات", "أمشاط وشوك تخريش وتقسيم العراميس", "قدد ألومنيوم ثقيلة 3م وميزان خيط طويل 20م للواجهات", "قدة وأفّة وميزان ليزر وخيط", "مسطرين وبروة ومحارة ووعاء قياس"),
